import cmath
import math


def cr_residuals(f, x, y, h=1e-5):
    fx = (f(complex(x + h, y)) - f(complex(x - h, y))) / (2 * h)
    fy = (f(complex(x, y + h)) - f(complex(x, y - h))) / (2 * h)
    return (fx.real - fy.imag, fy.real + fx.imag)


def analytic_near(f, x, y, r=0.01, tol=1e-6):
    pts = [(x, y)] + [(x + r * math.cos(2 * math.pi * k / 8), y + r * math.sin(2 * math.pi * k / 8)) for k in range(8)]
    return all(max(abs(a) for a in cr_residuals(f, px, py)) < tol for px, py in pts)
